package com.ferreteriahuaman.integration;
import com.ferreteriahuaman.service.*;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.dto.QuoteModels.*;import com.ferreteriahuaman.dto.ProductModels.*;import com.ferreteriahuaman.dto.PurchaseModels.Opening;import com.ferreteriahuaman.dto.QuoteModels.Line;import com.ferreteriahuaman.dto.QuoteModels.Details;import com.ferreteriahuaman.security.AuthModels.Identity;import com.ferreteriahuaman.security.AuthFailure;import java.math.BigDecimal;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.env.Environment;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import static org.assertj.core.api.Assertions.*;
@SpringBootTest @ActiveProfiles({"local","db"}) @Transactional @EnabledIfEnvironmentVariable(named="HUAMAN_DB_INTEGRATION",matches="true")
class QuoteDatabaseTest {
 @Autowired QuoteService quotes;@Autowired ProductService products;@Autowired CatalogService catalog;@Autowired PurchaseService purchases;@Autowired CashService cash;@Autowired SaleService sales;@Autowired AuthStore auth;@Autowired Environment env;@Autowired JdbcTemplate jdbc;Identity actor;String unique;long category;BigDecimal n(String s){return new BigDecimal(s);}
 @BeforeEach void setup(){var u=auth.lockUsername(env.getRequiredProperty("BOOTSTRAP_ADMIN_USUARIO")).orElseThrow();auth.context(u.username(),"INTEGRATION_ROLLBACK");UUID token=UUID.randomUUID();auth.createSession(u.id(),token,LocalDateTime.now(ZoneId.of("America/Lima")));actor=new Identity(u.id(),u.username(),u.nombres(),u.apellidos(),u.rol(),false,auth.permissions(u.id()),token,OffsetDateTime.now().plusMinutes(30));unique="INTEGRACION_"+UUID.randomUUID().toString().substring(0,8).toUpperCase();category=catalog.createCategory(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.CatalogModels.CategoryInput(unique,null,null)).id();}
 Product product(){long unit=jdbc.queryForObject("select id_unidad from huaman.unidad_medida where codigo_sunat='KGM'",Long.class);return products.create(actor,"INTEGRATION_ROLLBACK",new ProductInput(unique,"Producto cotizado",null,category,unit,true,n("0.001"),n("0.001"),"GRANEL",n("0"),null,"Base",n("10"),null));}
 long pres(Product p){return products.details(actor,p.id()).presentaciones().getFirst().id();}long id(Details d){return ((Number)d.cotizacion().get("id")).longValue();}
 Save input(Product p,String quantity,LocalDateTime version){return new Save(null,unique,"Observación de cotización",UUID.randomUUID(),version,List.of(new Line(pres(p),n(quantity))));}
 Action action(Details d,String reason){return new Action(UUID.randomUUID(),LocalDateTime.parse(d.cotizacion().get("version").toString()),((Number)d.cotizacion().get("revision")).intValue(),reason);}
 Details emit(Details d){return quotes.action(actor,"INTEGRATION_ROLLBACK",id(d),"emitir",action(d,null));}
 void open(){Assumptions.assumeTrue(jdbc.queryForObject("select count(*) from huaman.caja_diaria where estado_caja='ABIERTA' or fecha=timezone('America/Lima',now())::date",Long.class)==0,"No interferir con cajas reales");cash.open(actor,"INTEGRATION_ROLLBACK",new com.ferreteriahuaman.dto.CashModels.Open(n("0"),null,UUID.randomUUID()));jdbc.update("update huaman.parametro_sistema set valor='Negocio de integración' where clave='NEGOCIO.RAZON_SOCIAL'");}
 void price(Product p,String amount){var pr=products.details(actor,p.id()).presentaciones().getFirst();products.savePresentation(actor,"INTEGRATION_ROLLBACK",p.id(),pr.id(),new PresentationInput(pr.nombre(),pr.unidadVentaId(),n(pr.factorBase()),pr.permiteVenta(),pr.admiteFracciones(),n(pr.incrementoVenta()),n(pr.minimoVenta()),n(amount),pr.version()));}
 @Test void createEditEmitAndPrintDoNotReserveStockOrRequireCash(){long boxes=jdbc.queryForObject("select count(*) from huaman.caja_diaria",Long.class);var p=product();var input=input(p,"0.1",null);var d=quotes.save(actor,"INTEGRATION_ROLLBACK",null,input);assertThat(d.cotizacion().get("total")).isEqualTo("1.00");assertThat(quotes.save(actor,"INTEGRATION_ROLLBACK",null,input).cotizacion().get("id")).isEqualTo(id(d));d=quotes.save(actor,"INTEGRATION_ROLLBACK",id(d),input(p,"2",LocalDateTime.parse(d.cotizacion().get("version").toString())));assertThat(d.cotizacion().get("total")).isEqualTo("20.00");var request=action(d,null);d=quotes.action(actor,"INTEGRATION_ROLLBACK",id(d),"emitir",request);assertThat(d.cotizacion().get("estado")).isEqualTo("VIGENTE");assertThat(quotes.action(actor,"INTEGRATION_ROLLBACK",id(d),"emitir",request).cotizacion().get("id")).isEqualTo(id(d));var print=action(d,null);quotes.action(actor,"INTEGRATION_ROLLBACK",id(d),"imprimir",print);quotes.action(actor,"INTEGRATION_ROLLBACK",id(d),"imprimir",print);assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("0.000000");assertThat(jdbc.queryForObject("select count(*) from huaman.caja_diaria",Long.class)).isEqualTo(boxes);assertThat(quotes.list(actor,unique,"VIGENTE",null,null,0,20).total()).isEqualTo(1);jdbc.execute("set constraints all immediate");}
 @Test void conversionPreservesQuotedPriceAndOnlyConfirmedSaleMovesMoneyAndStock(){open();var p=product();purchases.opening(actor,"INTEGRATION_ROLLBACK",new Opening(p.id(),n("10"),n("1"),UUID.randomUUID(),List.of()));var d=emit(quotes.save(actor,"INTEGRATION_ROLLBACK",null,input(p,"1",null)));price(p,"12");var request=new Convert(UUID.randomUUID(),LocalDateTime.parse(d.cotizacion().get("version").toString()),"N");long sale=quotes.convert(actor,"INTEGRATION_ROLLBACK",id(d),request).ventaId();assertThat(quotes.convert(actor,"INTEGRATION_ROLLBACK",id(d),request).ventaId()).isEqualTo(sale);var v=sales.details(actor,sale);assertThat(v.venta().get("cotizacionId")).isEqualTo(id(d));assertThat(v.venta().get("cotizacionVigenteHasta")).isEqualTo(d.cotizacion().get("vigenteHasta"));assertThat(v.venta().get("total")).isEqualTo("10.00");assertThat(v.pagos()).isEmpty();assertThat(quotes.details(actor,id(d)).cotizacion().get("estado")).isEqualTo("VIGENTE");assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("10.000000");long series=jdbc.queryForObject("select min(id_serie) from huaman.serie_comprobante where tipo_comprobante='N' and estado='A'",Long.class);sales.confirm(actor,"INTEGRATION_ROLLBACK",sale,new com.ferreteriahuaman.dto.SaleModels.Confirm(series,LocalDateTime.parse(v.venta().get("version").toString()),List.of(new com.ferreteriahuaman.dto.SaleModels.Payment("EFECTIVO",n("10"),n("10"),null,null,null)),List.of()));assertThat(quotes.details(actor,id(d)).cotizacion().get("estado")).isEqualTo("CONVERTIDA");assertThat(products.details(actor,p.id()).producto().stockActual()).isEqualTo("9.000000");assertThat(cash.current().caja().efectivo()).isEqualTo("10.00");jdbc.execute("set constraints all immediate");}
 @Test void discardingLinkedDraftAllowsAnotherConversionWithoutDuplicatingActiveSale(){open();var p=product();var d=emit(quotes.save(actor,"INTEGRATION_ROLLBACK",null,input(p,"1",null)));long first=quotes.convert(actor,"INTEGRATION_ROLLBACK",id(d),new Convert(UUID.randomUUID(),LocalDateTime.parse(d.cotizacion().get("version").toString()),"N")).ventaId();var v=sales.details(actor,first);sales.discard(actor,"INTEGRATION_ROLLBACK",first,new com.ferreteriahuaman.dto.SaleModels.Discard(UUID.randomUUID(),LocalDateTime.parse(v.venta().get("version").toString()),"Corrección de venta cotizada"));d=quotes.details(actor,id(d));assertThat(d.cotizacion().get("ventaId")).isNull();long second=quotes.convert(actor,"INTEGRATION_ROLLBACK",id(d),new Convert(UUID.randomUUID(),LocalDateTime.parse(d.cotizacion().get("version").toString()),"N")).ventaId();assertThat(second).isNotEqualTo(first);assertThat(jdbc.queryForObject("select count(*) from huaman.venta where id_cotizacion=? and estado='A'",Long.class,id(d))).isEqualTo(1);}
 @Test void emittedQuoteCanBeCopiedAtCurrentPricesButCannotBeEdited(){var p=product();var d=emit(quotes.save(actor,"INTEGRATION_ROLLBACK",null,input(p,"1",null)));price(p,"12");var copied=quotes.action(actor,"INTEGRATION_ROLLBACK",id(d),"copiar",action(d,null));assertThat(copied.cotizacion().get("estado")).isEqualTo("BORRADOR");assertThat(copied.cotizacion().get("total")).isEqualTo("12.00");assertThatThrownBy(()->quotes.save(actor,"INTEGRATION_ROLLBACK",id(d),input(p,"2",LocalDateTime.parse(d.cotizacion().get("version").toString())))).isInstanceOf(AuthFailure.class);}
 @Test void cancellationIsIdempotentAndAnotherSellerCannotRead(){var p=product();var d=quotes.save(actor,"INTEGRATION_ROLLBACK",null,input(p,"1",null));var other=new Identity(actor.id()+999,"otro","Otro","Usuario","VEN",false,Set.of("COC.COTIZAR"),UUID.randomUUID(),OffsetDateTime.now().plusMinutes(30));assertThatThrownBy(()->quotes.details(other,id(d))).isInstanceOf(AuthFailure.class);var request=action(d,"Propuesta cancelada por el interesado");quotes.action(actor,"INTEGRATION_ROLLBACK",id(d),"anular",request);assertThat(quotes.action(actor,"INTEGRATION_ROLLBACK",id(d),"anular",request).cotizacion().get("estado")).isEqualTo("ANULADA");}
 @Test void staleVersionIsRejected(){var p=product();var d=quotes.save(actor,"INTEGRATION_ROLLBACK",null,input(p,"1",null));assertThatThrownBy(()->quotes.save(actor,"INTEGRATION_ROLLBACK",id(d),input(p,"2",LocalDateTime.parse(d.cotizacion().get("version").toString()).minusSeconds(1)))).isInstanceOf(AuthFailure.class);}

 Details expired(Product p){long id=jdbc.queryForObject("insert into huaman.cotizacion(id_vendedor,nombre_interesado,fecha,vigente_hasta) values(?,?,timezone('America/Lima',now())::date-20,timezone('America/Lima',now())::date-1) returning id_cotizacion",Long.class,actor.id(),unique);jdbc.update("insert into huaman.detalle_cotizacion(id_cotizacion,id_producto,id_presentacion,cantidad) values(?,?,?,1)",id,p.id(),pres(p));String previous=jdbc.queryForObject("select coalesce(current_setting('app.proceso',true),'')",String.class);jdbc.queryForObject("select set_config('app.proceso','EMITIR_COTIZACION',true)",String.class);try{jdbc.update("update huaman.cotizacion set estado_cotizacion='VIGENTE',clave_emision=?,emitida_en=timezone('America/Lima',now()),id_emite=? where id_cotizacion=?",UUID.randomUUID(),actor.id(),id);}finally{jdbc.queryForObject("select set_config('app.proceso',?,true)",String.class,previous);}return quotes.details(actor,id);}
 @Test void expiredQuoteRecalculatesPriceValidityAndRevisionExactlyOnce(){var p=product();var old=expired(p);assertThat(old.cotizacion().get("estado")).isEqualTo("VENCIDA");assertThat(quotes.list(actor,unique,"VENCIDA",null,null,0,20).total()).isEqualTo(1);price(p,"12");var request=action(old,null);var updated=quotes.action(actor,"INTEGRATION_ROLLBACK",id(old),"recalcular",request);assertThat(updated.cotizacion().get("estado")).isEqualTo("VIGENTE");assertThat(updated.cotizacion().get("total")).isEqualTo("12.00");assertThat(updated.cotizacion().get("revision")).isEqualTo(2);assertThat(updated.cotizacion().get("fecha")).isEqualTo(updated.cotizacion().get("hoy"));assertThat(quotes.action(actor,"INTEGRATION_ROLLBACK",id(old),"recalcular",request).cotizacion().get("revision")).isEqualTo(2);jdbc.execute("set constraints all immediate");}
 @Test void expiredQuoteCannotConvertWithoutRecalculation(){open();var p=product();var d=expired(p);assertThatThrownBy(()->quotes.convert(actor,"INTEGRATION_ROLLBACK",id(d),new Convert(UUID.randomUUID(),LocalDateTime.parse(d.cotizacion().get("version").toString()),"N"))).isInstanceOf(org.springframework.dao.DataAccessException.class);}
}
